import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 202;
    static final int INF = 0x3f3f3f3f;
    static int[][] flow = new int[MAXN][MAXN];
    static int[][] cap = new int[MAXN][MAXN];
    static int[] pre = new int[MAXN];
    static int[] dist = new int[MAXN];
    static int[][] gridA = new int[11][11];
    static int[][] gridB = new int[11][11];
    static int n, t, bi, bj;
    static int[][] matrix = new int[101][101];
    static List<Integer> ca = new ArrayList<>();
    static List<Integer> cb = new ArrayList<>();
    static List<Integer> cc = new ArrayList<>();
    static int[][] directions = {{0,1},{0,-1},{1,0},{-1,0}};
    static final int INF_VAL = INF + 1;

    public static int computeMaxFlow(int n, int s, int e) {
        int total = 0;
        while (true) {
            Arrays.fill(pre, -1);
            Arrays.fill(dist, 0);
            dist[s] = INF;
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            while (!q.isEmpty() && pre[e] < 0) {
                int u = q.poll();
                for (int v = 0; v < n; v++) {
                    if (pre[v] < 0 && cap[u][v] - flow[u][v] > 0) {
                        pre[v] = u;
                        dist[v] = Math.min(dist[u], cap[u][v] - flow[u][v]);
                        q.offer(v);
                    }
                }
            }
            if (pre[e] < 0) break;
            for (int v = e; v != s; v = pre[v]) {
                flow[pre[v]][v] += dist[e];
                flow[v][pre[v]] -= dist[e];
            }
            total += dist[e];
        }
        return total;
    }

    public static void traverse(int A, int B, int[] visited, boolean check) {
        Queue<int[]> q = new LinkedList<>();
        int n = visited.length;
        int A_idx = A * n + B;
        visited[A_idx] = 0;
        q.offer(new int[]{A, B});
        while (!q.isEmpty()) {
            int[] p = q.poll();
            int pIdx = p[0] * n + p[1];
            int dis = visited[pIdx];
            if (check && (matrix[bi * n + bj][pIdx] <= dis || t <= dis)) {
                if (matrix[bi * n + bj][pIdx] < dis || t < dis) {
                    visited[pIdx] = INF_VAL;
                }
                continue;
            }
            for (int d = 0; d < 4; d++) {
                int ni = p[0] + directions[d][0];
                int nj = p[1] + directions[d][1];
                if (ni < 0 || nj < 0 || ni >= n || nj >= n) continue;
                if (gridB[ni][nj] < '0' || gridB[ni][nj] > '9') continue;
                int qIdx = ni * n + nj;
                if (visited[qIdx] != 0 && visited[qIdx] != INF_VAL) continue;
                if (visited[qIdx] == 0) continue;
                if (visited[qIdx] != 0) {
                    visited[qIdx] = dis + 1;
                    q.offer(new int[]{ni, nj});
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());
        for (int i = 0; i < n; i++) {
            String lineA = br.readLine();
            for (int j = 0; j < n; j++) {
                gridA[i][j] = lineA.charAt(j);
            }
        }
        for (int i = 0; i < n; i++) {
            String lineB = br.readLine();
            for (int j = 0; j < n; j++) {
                gridB[i][j] = lineB.charAt(j);
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (gridA[i][j] == 'Z') {
                    bi = i;
                    bj = j;
                }
            }
        }
        for (int[] row : matrix) {
            Arrays.fill(row, INF);
        }
        int size = n * n;
        int[] visited = new int[size];
        Arrays.fill(visited, -1);
        traverse(bi, bj, visited, false);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (gridA[i][j] >= '1' && gridA[i][j] <= '9') {
                    traverse(i, j, visited, true);
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (gridA[i][j] >= '0' && gridA[i][j] <= '9') {
                    int p = i * n + j;
                    cap[p + 2 + size][1] = gridA[i][j] - '0';
                }
            }
        }
        int z = bi * n + bj;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (gridB[i][j] >= '0' && gridB[i][j] <= '9') {
                    int p = i * n + j;
                    cap[0][p + 2] = gridB[i][j] - '0';
                    for (int k = 0; k < ca.size(); k++) {
                        int ii = ca.get(k);
                        int jj = cb.get(k);
                        int qIdx = ii * n + jj;
                        if (matrix[p][qIdx] < INF) {
                            cap[p + 2][qIdx + 2 + size] = INF;
                        }
                    }
                }
            }
        }
        System.out.println(computeMaxFlow(2 + size, 0, 1));
    }
}
